using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;
namespace CircuitoStudio {
public sealed class ContactTimeForm:Form {
Project project;Circuit circuit;ContactTimeStudy study;List<Action> readers=new List<Action>();List<ClearingTimeRecord> records=new List<ClearingTimeRecord>();ListBox library=new ListBox{Dock=DockStyle.Fill};TextBox result=new TextBox{Dock=DockStyle.Bottom,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Height=300};public bool Changed{get;private set;}
public ContactTimeForm(Project p,Circuit c){project=p;circuit=c;study=c.ContactTimeStudy==null?new ContactTimeStudy():c.ContactTimeStudy.Copy();if(study.Evidence!=null)records.Add(study.Evidence.Copy());Text="Contato e tempo de desligamento — "+c.Id;Size=new Size(1380,850);MinimumSize=new Size(1120,700);Font=new Font("Segoe UI",10);var split=new SplitContainer{Dock=DockStyle.Fill};split.Size=new Size(1320,720);split.SplitterDistance=550;var tabs=new TabControl{Dock=DockStyle.Fill};var rule=new TabPage("Regra e aplicabilidade");var evidence=new TabPage("Dispositivo e monitoramento IT");rule.Controls.Add(TypedFields.Create(study.Rule,readers));evidence.Controls.Add(TypedFields.Create(study,readers));tabs.TabPages.AddRange(new[]{rule,evidence});split.Panel1.Controls.Add(tabs);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=135};Add(bar,"Importar tempos CSV",Import);Add(bar,"Modelo vazio",()=>Export(false));Add(bar,"Modelo do dispositivo",()=>Export(true));Add(bar,"Usar evidência selecionada",SelectRecord);Add(bar,"Limpar evidência",()=>{study.Evidence=null;result.Text="Evidência retirada da cópia. Salve para alterar o circuito.";});Add(bar,"Avaliar cópia",()=>EvaluateDraft(false));Add(bar,"Salvar estudo",()=>EvaluateDraft(true));Add(bar,"Remover estudo",()=>{circuit.ContactTimeStudy=null;Changed=true;result.Text="Estudo removido; dados da proteção e caso de falta preservados.";});split.Panel2.Controls.Add(library);split.Panel2.Controls.Add(result);split.Panel2.Controls.Add(bar);Controls.Add(split);RefreshRecords();result.Text="Defina fonte/edição/cláusula e limites da regra, sem presumir norma automática. Tempo precisa cobrir interrupção total nas condições/dispositivo exatos. A corrente residual pode diferir da corrente da falta; não use curva t-I de sobrecorrente como curva residual. Modelo do dispositivo exporta apenas estrutura/contexto com PREENCHER. IT1 com continuidade exige IMD/ensaio e plano de localização/reparo; não se inventa tempo de corte.";}
void Add(Control parent,string text,Action action){var b=new Button{Text=text,AutoSize=true,Height=32};b.Click+=(s,e)=>{try{action();}catch(Exception ex){result.Text="Nenhuma alteração no circuito. "+ex.Message;}};parent.Controls.Add(b);}
void Read(){foreach(var reader in readers)reader();study.Validate();}
public void LoadLibrary(IEnumerable<ClearingTimeRecord> source){var copy=source.Select(r=>r.Copy()).ToList();foreach(var row in copy)row.Validate();records=copy;RefreshRecords();}
void RefreshRecords(){library.Items.Clear();foreach(var row in records)library.Items.Add(TypedFields.Friendly(row.Device)+" / "+row.Manufacturer+" / "+row.Reference+" / "+row.MinimumCurrentA+"–"+row.MaximumCurrentA+" A / ≤"+row.UpperSeconds+" s total");if(library.Items.Count>0)library.SelectedIndex=0;}
void SelectRecord(){if(library.SelectedIndex<0)throw new InvalidDataException("Selecione uma evidência.");study.Evidence=records[library.SelectedIndex].Copy();result.Text="Evidência copiada. Avalie a cópia antes de salvar; dispositivo/configuração, corrente e tempo total serão conferidos.";}
void Import(){using(var d=new OpenFileDialog{Filter="Evidências CSV|*.csv"})if(d.ShowDialog(this)==DialogResult.OK)LoadLibrary(ContactTime.Import(d.FileName));}
void Export(bool current){Read();using(var d=new SaveFileDialog{Filter="Evidências CSV|*.csv",FileName="tempos-totais.csv"})if(d.ShowDialog(this)==DialogResult.OK)ContactTime.Export(current?new[]{ContactTime.Template(project,circuit,study.Device)}:new ClearingTimeRecord[0],d.FileName);}
public ContactTimeResult EvaluateDraft(bool commit){Read();var evaluated=ContactTime.Evaluate(project,circuit,study);if(commit){ContactTime.Apply(project,circuit,study);Changed=true;}result.Text=evaluated.Status+"\r\n"+evaluated.Detail;return evaluated;}
}
partial class Studio {void ConfigureContactTime(){if(circuit==null)throw new InvalidOperationException("Selecione um circuito.");using(var form=new ContactTimeForm(project,circuit)){form.ShowDialog(this);if(form.Changed)Change();}}}
}
